    cin >> n;
    for (int i = 1; i <= n; ++i)
        cin >> p[i];
    for (int i = 1; i <= n; ++i) {
        for (int j = i; j <= n; ++j) {
            dp[j] = max(dp[j], dp[j - i] + p[i]);
        }
    }
    cout << dp[n] << endl;
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int n;
int l[100010], r[100010];
int h[100010], chk[100010] = {1};
int ans;

void dfs(int u) {
    if (!u)
        return;
    dfs(l[u]);
    dfs(r[u]);
    h[u] = max(h[l[u]], h[r[u]]) + 1;
    chk[u] = chk[l[u]] && chk[r[u]] && (h[l[u]] == h[r[u]]);
    ans += chk[u];
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++)
        cin >> l[i] >> r[i];
    ans = 0;
    dfs(1);
    cout << ans << endl;
    return 0;
}
